    lines = [str(T)]
    for _ in range(T):
        n = draw(st.integers(3, 6))
        base = list(range(1, n + 1))
        mode = draw(st.integers(0, 3))
        if mode == 0:
            p = base[:]
        elif mode == 1:
            p = base[::-1]
        else:
            p = draw(st.permutations(base))
            p = list(p)
        lines.append(str(n))
        lines.append(" ".join(map(str, p)))
    return "\n".join(lines) + "\n"


