    n = len(p)
    start = tuple(p)
    goal = tuple(range(1, n + 1))
    if start == goal:
        return 0
    dist = {start: 0}
    q = deque([start])
    while q:
        cur = q.popleft()
        d = dist[cur]
        for k in range(1, n + 1):
            # sort positions 1..k-1 and k+1..N (1-indexed), k stays fixed
            pre = sorted(cur[0:k - 1])
            mid = [cur[k - 1]]
            suf = sorted(cur[k:])
            nxt = tuple(pre + mid + suf)
            if nxt not in dist:
                dist[nxt] = d + 1
                if nxt == goal:
                    return d + 1
                q.append(nxt)
    return None


