    for _ in range(t):
        n = int(tok[idx]); idx += 1
        p = [int(x) for x in tok[idx:idx + n]]
        idx += n
        cases.append((n, p))
    return t, cases, idx, len(tok)


def validate(inp: str) -> bool:
    try:
        tok = inp.split()
        if not tok:
            return False
        t = int(tok[0])
        if not (1 <= t <= 10**5):
            return False
