            return False
        return total <= 2 * 10**5
    except Exception:
        return False


def _apply(p, k):
    q = list(p)
    n = len(q)
    if k >= 2:
        q[:k - 1] = sorted(q[:k - 1])
    if k <= n - 1:
        q[k:] = sorted(q[k:])
    return tuple(q)


def _min_ops(p):
    n = len(p)
    target = tuple(range(1, n + 1))
    start = tuple(p)
    if start == target:
        return 0
    dist = {start: 0}
    dq = deque([start])
